//! Game adapters for the two distinct20-record cosmetic queues.
use super::super::{Game,json,original_bullet_impacts20};
impl Game{
 pub(crate) fn advance_native_hardware_movement(&mut self,index:usize){
  let u=self.units[index].clone();let member=u.native_slot.and_then(|s|self.native_group_rosters.members.get(s)).and_then(Option::as_ref);let w=u.native_hardware_slot.and_then(|s|self.native_hardware_pool.get(usize::from(s))).map(|s|s.attributes);
  let input=super::tracks::Input{position:[(u.x/2.).floor()as i16,(u.y/2.).floor()as i16],family:super::super::original_combat::animation_family(&u.kind),direction:super::super::original_combat::facing(u.angle),frame:u.native_move_frame,flags31:member.map_or(4,|m|m.flags31),flags71:u.native_initiative_scan.flags71,hp:w.map_or(u.hp as i16,|v|v.word(8)),maximum:w.map_or(u.max_hp as i16,|v|v.word(10)),multiplayer:self.multiplayer};
  let mut world=TrackWorld{map:&self.map,rng:&mut self.native_cosmetic_rng};let smoke=&mut self.native_smoke20;let frame=super::tracks::moved(&mut smoke.tracks,&mut smoke.records,input,&mut world);self.units[index].native_move_frame=frame;self.units[index].native_frame32=i16::from(frame);
 }
 pub(crate) fn update_native_track_effects(&mut self){let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));let world=self.map.wall_tile_lookup["nativeWorld"].as_u64().map_or([0,3,1,4,2][self.map.world.min(4)],|n|n as u8);self.native_smoke20.tracks.advance(camera,size,world,self.motion_tick&1==0);}
 pub(crate) fn native_track_visuals(&self)->Vec<serde_json::Value>{self.native_smoke20.tracks.draws.iter().map(|d|json!({"id":d.slot,"sprite":d.sprite,"x":i32::from(d.position[0])*2,"y":i32::from(d.position[1])*2,"nativeInheritedPalette":true,"team":null,"scale":1.,"rotation":0.})).collect()}
 pub(crate) fn spawn_native_smoke(&mut self,point:[i16;2]){self.native_smoke20.spawn(point);}
 pub(crate) fn spawn_native_bullet_ground_impact(&mut self,point:[i16;2]){let terrain=self.native_terrain(i32::from(point[0]),i32::from(point[1]));self.native_bullet_impacts20.spawn(point,terrain);}
 pub(crate) fn update_native_cosmetics20(&mut self){let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));let pulse=self.motion_tick&1==0;self.native_smoke20.advance(camera,pulse);let world=self.map.wall_tile_lookup["nativeWorld"].as_u64().map_or([0,3,1,4,2][self.map.world.min(4)],|n|n as u8);self.native_bullet_impacts20.advance(camera,size,original_bullet_impacts20::Profile::for_world(world),pulse);}
 pub(crate) fn native_cosmetic20_visuals(&self)->Vec<serde_json::Value>{let mut out=Vec::new();for d in &self.native_smoke20.draws{out.push(json!({"id":d.slot,"kind":"smoke","sprite":d.sprite,"x":i32::from(d.position[0])*2,"y":i32::from(d.position[1])*2,"nativeInheritedPalette":true,"team":null,"scale":1.,"rotation":0.}));}for d in &self.native_bullet_impacts20.draws{out.push(json!({"id":20+d.slot,"kind":"groundImpact","sprite":d.sprite,"x":i32::from(d.position[0])*2,"y":i32::from(d.position[1])*2,"nativeInheritedPalette":true,"team":null,"scale":1.,"rotation":0.}));}out}
}
struct TrackWorld<'a>{map:&'a super::super::Map,rng:&'a mut u32}
impl super::tracks::World for TrackWorld<'_>{fn random(&mut self)->u16{*self.rng=self.rng.wrapping_mul(214013).wrapping_add(2531011);((*self.rng>>16)&32767)as u16}fn terrain(&self,cell:i16)->u8{let i=cell as u16 as usize;let(x,y)=(i&127,i>>7);if x<self.map.width&&y<self.map.height{self.map.terrain_codes.get(y*self.map.width+x).copied().unwrap_or(127)}else{self.map.native_terrain_plane.get(i).copied().unwrap_or(127)}}}
#[cfg(test)]mod tests{use super::*;
 #[test]fn hardware_movement_writes_the_real_track_pool_and_only_the_cosmetic_stream(){let mut g=Game::new(0,1,7719);g.units.clear();g.map.original=true;g.map.terrain_codes=vec![0;g.map.width*g.map.height];g.map.native_terrain_plane=vec![0;16384];g.spawn("light",0,640.,640.,1,None);g.units[0].angle=0.;g.units[0].native_move_frame=2;g.native_cosmetic_rng=1;let words=g.original_rng.words;g.advance_native_hardware_movement(0);assert_eq!(g.units[0].native_move_frame,1);assert_eq!(g.units[0].native_frame32,1);assert!(g.native_smoke20.tracks.records.iter().any(|r|r.position[0]!=-1));assert_eq!(g.original_rng.words,words);let mut expected=1u32;for _ in 0..4{expected=expected.wrapping_mul(214013).wrapping_add(2531011);}assert_eq!(g.native_cosmetic_rng,expected);}
}
